CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,name TEXT NOT NULL,is_admin BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tenants(id TEXT PRIMARY KEY,name TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS memberships(user_id TEXT REFERENCES users(id),tenant_id TEXT REFERENCES tenants(id),role TEXT NOT NULL DEFAULT 'owner',PRIMARY KEY(user_id,tenant_id));
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS bots(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),name TEXT NOT NULL,protocol TEXT NOT NULL CHECK(protocol IN ('mock','napcat','euler')),expected_uin TEXT NOT NULL DEFAULT '',desired_state TEXT NOT NULL DEFAULT 'stopped',observed_state TEXT NOT NULL DEFAULT 'stopped',generation INTEGER NOT NULL DEFAULT 0,revision INTEGER NOT NULL DEFAULT 1,applied_revision INTEGER NOT NULL DEFAULT 0,health JSONB NOT NULL DEFAULT '{}',last_error TEXT,deleted_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS bots_tenant ON bots(tenant_id);
CREATE TABLE IF NOT EXISTS bot_config_revisions(bot_id TEXT NOT NULL REFERENCES bots(id),revision INTEGER NOT NULL,config JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(bot_id,revision));
CREATE TABLE IF NOT EXISTS secrets(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),bot_id TEXT NOT NULL UNIQUE REFERENCES bots(id),ciphertext TEXT NOT NULL,updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS instances(bot_id TEXT PRIMARY KEY REFERENCES bots(id),node_id TEXT NOT NULL DEFAULT 'local',generation INTEGER NOT NULL,ai_port INTEGER NOT NULL UNIQUE,protocol_port INTEGER NOT NULL UNIQUE,token TEXT NOT NULL,heartbeat_at TIMESTAMPTZ,health JSONB NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS qq_bindings(bot_id TEXT PRIMARY KEY REFERENCES bots(id),qq_uin TEXT NOT NULL UNIQUE,bound_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS login_sessions(id TEXT PRIMARY KEY,bot_id TEXT NOT NULL REFERENCES bots(id),generation INTEGER NOT NULL,state TEXT NOT NULL,sequence INTEGER NOT NULL DEFAULT 0,qr TEXT,qq_uin TEXT,message TEXT,expires_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS one_active_login ON login_sessions(bot_id) WHERE state NOT IN ('online','expired','canceled','failed');
CREATE TABLE IF NOT EXISTS commands(id TEXT PRIMARY KEY,bot_id TEXT NOT NULL REFERENCES bots(id),idempotency_key TEXT NOT NULL,generation INTEGER NOT NULL,kind TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',error TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),finished_at TIMESTAMPTZ,UNIQUE(bot_id,idempotency_key));
CREATE TABLE IF NOT EXISTS audit_events(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,event TEXT NOT NULL,bot_id TEXT,detail JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
